$alraesy_228$::jsonb) AS x(g integer,p integer,q text,o jsonb,a integer,t integer,m integer,s text,c text)
), author_user AS (
  SELECT id,display_name FROM users
  WHERE id=19 AND name='Dr. Waleed Al-Sibakhi' AND archived=false
), inserted AS (
  INSERT INTO questions(company_id,category,priority,question,
    answer1,answer2,answer3,answer4,option_count,correct_answer,points,active,created_by)
  SELECT NULL,'معلومات صيدلانية',s.p,s.q,
    s.o->>0,s.o->>1,CASE WHEN jsonb_array_length(s.o)>2 THEN s.o->>2 ELSE NULL END,
    CASE WHEN jsonb_array_length(s.o)>3 THEN s.o->>3 ELSE NULL END,
    jsonb_array_length(s.o),s.a,s.t,TRUE,author_user.id
  FROM source s CROSS JOIN author_user
  WHERE NOT EXISTS(SELECT 1 FROM questions q
    WHERE q.company_id IS NULL AND q.category='معلومات صيدلانية' AND q.question=s.q)
  RETURNING id,created_by,question,priority,points,option_count,correct_answer
)
INSERT INTO audit_events(actor_id,actor_name,scope,company_id,action,target_type,
  target_id,before_value,after_value)
SELECT NULL,'استيراد إداري بطلب المالك','public',NULL,'question.create','question',i.id,NULL,
  jsonb_build_object('category','معلومات صيدلانية','question',i.question,
    'priority',i.priority,'points',i.points,'correctAnswer',i.correct_answer,
    'optionCount',i.option_count,'createdBy',i.created_by,
    'sourceUrl',s.s,'sourceMessageId',s.m,'sourceGroup',s.g,'originalTopic',s.c)
FROM inserted i JOIN source s ON s.q=i.question;